-- 소비패턴 관리 에이전트용 확장 테이블 (docs/agent-spec.md 5절)
-- 기존 테이블(001_init.sql)은 변경하지 않는다.

-- 소비 카테고리
CREATE TABLE IF NOT EXISTS "spending_categories" (
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- 카테고리 코드 (FOOD, CAFE, TRANSPORT ...)
	"code" VARCHAR(30) NOT NULL UNIQUE,
	-- 카테고리명
	"name" VARCHAR(50) NOT NULL,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "spending_categories" IS '소비 카테고리';
COMMENT ON COLUMN "spending_categories"."id" IS '카테고리 ID';
COMMENT ON COLUMN "spending_categories"."code" IS '카테고리 코드';
COMMENT ON COLUMN "spending_categories"."name" IS '카테고리명';

-- 가맹점 -> 카테고리 매핑 (룰·LLM 캐시·사용자 보정)
CREATE TABLE IF NOT EXISTS "merchant_category_map" (
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- 회원 ID (NULL이면 공통 룰, 값이 있으면 그 회원의 보정)
	"user_id" UUID,
	-- 정규화한 가맹점명
	"merchant_key" VARCHAR(100) NOT NULL,
	"category_id" BIGINT NOT NULL,
	-- 분류 출처: RULE 룰 / LLM 자동분류 / USER 사용자 보정
	"source" VARCHAR(10) NOT NULL,
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

-- user_id가 NULL인 공통 룰도 가맹점당 1건만 허용
CREATE UNIQUE INDEX "uq_merchant_map_user_key"
ON "merchant_category_map" (COALESCE("user_id"::text, ''), "merchant_key");

COMMENT ON TABLE "merchant_category_map" IS '가맹점 카테고리 매핑';
COMMENT ON COLUMN "merchant_category_map"."user_id" IS '회원 ID (NULL이면 공통 룰)';
COMMENT ON COLUMN "merchant_category_map"."merchant_key" IS '정규화한 가맹점명';
COMMENT ON COLUMN "merchant_category_map"."source" IS '분류 출처: RULE 룰 / LLM 자동분류 / USER 사용자 보정';

-- 예산
CREATE TABLE IF NOT EXISTS "budgets" (
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	"user_id" UUID NOT NULL,
	-- 카테고리 ID (NULL이면 월 전체 예산)
	"category_id" BIGINT,
	-- 해당 월 1일
	"budget_month" DATE NOT NULL,
	-- 예산 금액 (원)
	"amount" BIGINT NOT NULL,
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

CREATE UNIQUE INDEX "uq_budgets_user_cat_month"
ON "budgets" ("user_id", COALESCE("category_id", 0), "budget_month");

COMMENT ON TABLE "budgets" IS '월 소비 예산';
COMMENT ON COLUMN "budgets"."category_id" IS '카테고리 ID (NULL이면 월 전체 예산)';
COMMENT ON COLUMN "budgets"."budget_month" IS '해당 월 1일';
COMMENT ON COLUMN "budgets"."amount" IS '예산 금액 (원)';

-- 에이전트 챗 기록
CREATE TABLE IF NOT EXISTS "agent_messages" (
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	"user_id" UUID NOT NULL,
	"session_id" UUID NOT NULL,
	-- 발화자: USER 사용자 / AGENT 에이전트
	"role" VARCHAR(10) NOT NULL,
	"content" TEXT NOT NULL,
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

CREATE INDEX "idx_agent_messages_session"
ON "agent_messages" ("session_id", "created_at");

COMMENT ON TABLE "agent_messages" IS '에이전트 챗 기록';
COMMENT ON COLUMN "agent_messages"."role" IS '발화자: USER 사용자 / AGENT 에이전트';

ALTER TABLE "merchant_category_map"
ADD FOREIGN KEY("user_id") REFERENCES "users"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "merchant_category_map"
ADD FOREIGN KEY("category_id") REFERENCES "spending_categories"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "budgets"
ADD FOREIGN KEY("user_id") REFERENCES "users"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "budgets"
ADD FOREIGN KEY("category_id") REFERENCES "spending_categories"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "agent_messages"
ADD FOREIGN KEY("user_id") REFERENCES "users"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
